        }
        var initial=await Capture();var closing=await Capture();await Guard();if(JsonSerializer.Serialize(initial)!=JsonSerializer.Serialize(closing))throw new InvalidOperationException("The complete original functional book/FX scope changed.");return CompanyInventorySourceReview.Copy(closing);
